"""Inspect the current workspace folder and any SQLite databases in it.

This helper only reads: it lists files and runs read-only introspection
queries (sqlite_master) against candidate database files. It writes nothing.
"""
import os
import sqlite3

HERE = os.path.dirname(os.path.abspath(__file__))

CANDIDATE_SUFFIXES = (".db", ".sqlite", ".sqlite3", ".db3")


def main() -> None:
    print("Workspace directory:", HERE)
    print("\nFiles in workspace:")
    for name in sorted(os.listdir(HERE)):
        full = os.path.join(HERE, name)
        if os.path.isdir(full):
            print(f"  [DIR ] {name}/")
        else:
            print(f"  [FILE] {name} ({os.path.getsize(full)} bytes)")

    # 1) Files with a database-like extension.
    candidates = [
        os.path.join(HERE, name)
        for name in sorted(os.listdir(HERE))
        if os.path.isfile(os.path.join(HERE, name))
        and name.lower().endswith(CANDIDATE_SUFFIXES)
    ]

    # 2) Any other file that happens to be an SQLite database.
    for name in sorted(os.listdir(HERE)):
        full = os.path.join(HERE, name)
        if not os.path.isfile(full) or full in candidates:
            continue
        try:
            conn = sqlite3.connect(full)
            try:
                conn.execute("SELECT name FROM sqlite_master LIMIT 1").fetchone()
                candidates.append(full)
            finally:
                conn.close()
        except Exception:
            # Not an SQLite database; ignore.
            pass

    if not candidates:
        print("\nNo SQLite database found in the workspace folder.")
        return

    for full in sorted(set(candidates)):
        print(f"\n=== {os.path.basename(full)} ===")
        try:
            conn = sqlite3.connect(full)
            try:
                cur = conn.cursor()
                cur.execute(
                    "SELECT type, name, sql FROM sqlite_master "
                    "WHERE type IN ('table', 'index') ORDER BY type, name"
                )
                rows = cur.fetchall()
                if not rows:
                    print("  (no tables or indexes)")
                for obj_type, obj_name, sql in rows:
                    print(f"  {obj_type.upper()}: {obj_name}")
                    if sql:
                        print(f"    SQL: {sql}")
            finally:
                conn.close()
        except Exception as exc:
            print(f"  ERROR opening as SQLite: {exc}")

    print("\nDone.")


if __name__ == "__main__":
    main()

"""Inspect the workspace to locate the SQLite database and report its schema.

Task-scoped helper: only lists files in the current directory and reads
SQLite schema metadata. No writes, no network, no other operations.
"""

import os
import sqlite3


def main() -> None:
    cwd = os.getcwd()
    print(f"Workspace directory: {cwd}")
    print("\nFiles in workspace:")
    for entry in sorted(os.listdir(cwd)):
        full = os.path.join(cwd, entry)
        kind = "dir" if os.path.isdir(full) else "file"
        size = os.path.getsize(full) if os.path.isfile(full) else "-"
        print(f"  {kind:4} {size:>10}  {entry}")

    db_candidates = [
        os.path.join(cwd, name)
        for name in sorted(os.listdir(cwd))
        if name.lower().endswith((".db", ".sqlite", ".sqlite3"))
        and os.path.isfile(os.path.join(cwd, name))
    ]

    if not db_candidates:
        print("\nNo SQLite database file found in the workspace.")
        return

    for db_path in db_candidates:
        print(f"\n=== Schema of {os.path.basename(db_path)} ===")
        try:
            with sqlite3.connect(db_path) as conn:
                conn.row_factory = sqlite3.Row
                cur = conn.cursor()
                tables = cur.execute(
                    "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
                ).fetchall()
                for table in tables:
                    tname = table["name"]
                    print(f"\nTable: {tname}")
                    for col in cur.execute(f'PRAGMA table_info("{tname}")'):
                        print(
                            f"  column: {col['name']}  type={col['type']} "
                            f"notnull={col['notnull']} default={col['dflt_value']} "
                            f"pk={col['pk']}"
                        )
        except sqlite3.Error as exc:
            print(f"  ERROR reading {db_path}: {exc}")


if __name__ == "__main__":
    main()

